#include <iostream>

struct Array {
    static constexpr std::size_t size = 5;
    int data_[size];

    class Iterator {
    public:
        Iterator() = default;
        explicit Iterator(int* p) : p_(p) {}

        int& operator*()  const { return *p_; }
        int* operator->() const { return p_; }

        Iterator& operator++()    { ++p_; return *this; }
        Iterator  operator++(int) { Iterator tmp = *this; ++p_; return tmp; }

        bool operator==(const Iterator& other) const { return p_ == other.p_; }
        bool operator!=(const Iterator& other) const { return p_ != other.p_; }

    private:
        int* p_ = nullptr;
    };

    Iterator begin() { return Iterator(data_); }
    Iterator end()   { return Iterator(data_ + size); }
};

#include <iostream>

class List {
    struct Node {
        int value;
        Node* next;
    };

public:
    class Iterator {
    public:
        Iterator() = default;
        explicit Iterator(Node* n) : node_(n) {}

        int& operator*()  const { return node_->value; }
        int* operator->() const { return &node_->value; }
        
        Iterator& operator++()    { node_ = node_->next; return *this; }
        Iterator  operator++(int) { Iterator tmp = *this; node_ = node_->next; return tmp; }

        bool operator==(const Iterator& other) const { return node_ == other.node_; }
        bool operator!=(const Iterator& other) const { return node_ != other.node_; }
        
        private:
        Node* node_ = nullptr;
    };
    
    Iterator begin() { return Iterator(head_); }
    Iterator end()   { return Iterator(nullptr); }

    List() = default;
    List(const List&) = delete;
    List& operator=(const List&) = delete;

    ~List() {
        while (head_) {
            Node* next = head_->next;
            delete head_;
            head_ = next;
        }
    }

    void push_back(int value) {
        Node* n = new Node{value, nullptr};
        if (tail_) {
            tail_->next = n;
        } else {
            head_ = n;
        }
        tail_ = n;
    }


private:
    Node* head_ = nullptr;
    Node* tail_ = nullptr;
};


int main() {
    Array arr{{1, 2, 3, 4, 5}};

    for (int x : arr) {
        std::cout << x << ' ';
    }
    std::cout << '\n';

    

    List list;
    for (int i = 1; i <= 5; ++i) {
        list.push_back(i);
    }

    for (int x : list) {
        std::cout << x << ' ';
    }
    std::cout << '\n';

}
